-- Seed 61 vendors from Pasar Malam KPMBP

-- Sesi Undian Aktif
SELECT 'PMK-2026-10', 'Pasar Malam KPMBP — Oktober 2026', NOW() - INTERVAL '1 day', NOW() + INTERVAL '2 days', 'open', 20, 5
WHERE NOT EXISTS (SELECT 1 FROM voting_sessions WHERE id='PMK-2026-10');

-- Pautkan semua peniaga aktif kepada sesi aktif
SELECT 'PMK-2026-10', id FROM vendors WHERE active = TRUE AND NOT EXISTS (
  SELECT 1 FROM session_vendors sv WHERE sv.session_id='PMK-2026-10' AND sv.vendor_id=vendors.id
);
